use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-cold-tail175";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let args=std::env::args().collect::<Vec<_>>();assert_eq!(args.len(),3);let label=&args[1];assert!(["control","candidate"].contains(&label.as_str()));let out=PathBuf::from(&args[2]);let root=Path::new(R);let frozen:Value=serde_json::from_slice(&fs::read(root.join(format!("frozen-{label}.json"))).unwrap()).unwrap();let mut libs=frozen["libraries"].as_object().unwrap().iter().map(|(k,v)|(k.clone(),v.as_str().unwrap().to_string())).collect::<BTreeMap<_,_>>();let dependency=root.join("frozen").join(label);let sha=fs::read_dir(&dependency).unwrap().map(|e|e.unwrap().path()).filter(|p|p.file_name().unwrap().to_str().unwrap().starts_with("libsha2-")).collect::<Vec<_>>();assert_eq!(sha.len(),1);libs.insert("sha2".into(),sha[0].display().to_string());assert_eq!(libs.len(),9);let binary=out.with_file_name(format!("{}-sdk",out.file_name().unwrap().to_str().unwrap()));assert!(!binary.exists());let mut argv=vec!["--edition=2021".to_string(),"-O".into(),"-C".into(),"target-cpu=native".into(),"-C".into(),"lto=fat".into(),"-C".into(),"codegen-units=1".into(),"-L".into(),format!("dependency={}",dependency.display())];let mut pins=BTreeMap::new();for(name,path)in &libs{argv.extend(["--extern".into(),format!("{name}={path}")]);pins.insert(path.clone(),hash(path));}for name in["probe.rs","perf.rs"]{let p=root.join(name);pins.insert(p.display().to_string(),hash(&p));}argv.extend([root.join("probe.rs").display().to_string(),"-o".into(),binary.display().to_string()]);assert!(Command::new("rustc").args(&argv).status().unwrap().success());fs::write(out.join("artifacts.json"),serde_json::to_vec_pretty(&json!({"binary":binary,"binary_sha256":hash(&binary),"libraries":libs,"input_pins":pins,"argv":argv,"native_flags_from_frozen_library_receipt":frozen["rustflags"]})).unwrap()).unwrap();println!("Linked{label}real replay with9explicit coherent frozen libraries");}
